/**
 * Weekly series (Mar 1, 8, 15, 22, 29) where the third occurrence has been
 * moved to Mar 18 via a RECURRENCE-ID override.
 */
export const RECURRING_EVENT_WITH_OVERRIDE = `BEGIN:VCALENDAR
VERSION:2.0
PRODID:-//Test//Test//EN
BEGIN:VEVENT
DTSTART:20250301T100000Z
DTEND:20250301T110000Z
SUMMARY:Weekly Meeting
RRULE:FREQ=WEEKLY;COUNT=5
UID:recurring-override-1
END:VEVENT
BEGIN:VEVENT
UID:recurring-override-1
RECURRENCE-ID:20250315T100000Z
DTSTART:20250318T100000Z
DTEND:20250318T113000Z
SUMMARY:Weekly Meeting (moved)
DESCRIPTION:Moved to Tuesday
LOCATION:Room C
URL:https://example.com/moved
END:VEVENT
END:VCALENDAR`

